package com.xericguide;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Loads only bundled, fixed-name resources; never loads downloaded guide content. */
public final class GuideBook
{
	private static final Logger log = LoggerFactory.getLogger(GuideBook.class);
	public static final List<String> IDS = List.of("first-raid", "tekton", "vespula", "vasa", "vanguards",
		"guardians", "shamans", "mystics", "muttadiles", "crabs", "ice-demon", "thieving", "tightrope",
		"preparation", "olm", "olm-solo", "olm-group", "challenge", "glossary");
	private final Map<String, GuidePage> pages;

	private GuideBook(Map<String, GuidePage> pages)
	{
		this.pages = Collections.unmodifiableMap(new LinkedHashMap<>(pages));
	}

	public static GuideBook load()
	{
		Map<String, GuidePage> pages = new LinkedHashMap<>();
		for (String id : IDS)
		{
			try (InputStream input = GuideBook.class.getResourceAsStream("guides/" + id + ".properties"))
			{
				pages.put(id, parse(id, input));
			}
			catch (IOException | IllegalArgumentException ex)
			{
				log.debug("Unable to load guide {}", id, ex);
				pages.put(id, new GuidePage(id, id + " (unavailable)", "Help", "This bundled guide could not be read.",
					"Use the source link below.", "Use the source link below.",
					List.of("Try disabling and enabling the plugin. If the problem remains, reinstall it from the Plugin Hub."),
					"Other guides still work. Report the affected guide name on the project issue tracker.",
					"https://oldschool.runescape.wiki/w/Chambers_of_Xeric/Strategies"));
			}
		}
		return new GuideBook(pages);
	}

	static GuidePage parse(String id, InputStream input) throws IOException
	{
		if (input == null)
		{
			throw new IOException("Missing bundled guide: " + id);
		}
		Properties properties = new Properties();
		properties.load(new InputStreamReader(input, StandardCharsets.UTF_8));
		List<String> steps = new ArrayList<>();
		for (int i = 1; i <= 20; i++)
		{
			String step = properties.getProperty("step." + i);
			if (step == null)
			{
				break;
			}
			if (step.isBlank())
			{
				throw new IOException("Empty step in " + id);
			}
			steps.add(step.trim());
		}
		if (steps.isEmpty())
		{
			throw new IOException("Guide has no steps: " + id);
		}
		String source = required(properties, "source");
		if (!source.startsWith("https://oldschool.runescape.wiki/w/"))
		{
			throw new IOException("Unexpected guide source");
		}
		return new GuidePage(id, required(properties, "title"), required(properties, "category"),
			required(properties, "before"), required(properties, "solo"), required(properties, "group"),
			steps, required(properties, "recovery"), source);
	}

	private static String required(Properties properties, String key) throws IOException
	{
		String value = properties.getProperty(key, "").trim();
		if (value.isEmpty())
		{
			throw new IOException("Missing guide field: " + key);
		}
		return value;
	}

	public List<GuidePage> getPages()
	{
		return List.copyOf(pages.values());
	}

	public GuidePage get(String id)
	{
		return pages.getOrDefault(id, pages.get("first-raid"));
	}
}

package com.xericguide;

import java.util.List;

/** Immutable content. There are deliberately no NPC or combat-state inputs. */
public final class GuidePage
{
	private final String id;
	private final String title;
	private final String category;
	private final String before;
	private final String solo;
	private final String group;
	private final List<String> steps;
