	public String getSolo() { return solo; }
	public String getGroup() { return group; }
	public List<String> getSteps() { return steps; }
	public String getRecovery() { return recovery; }
	public String getSource() { return source; }

	@Override
	public String toString()
	{
		return title;
	}
}

package com.xericguide;

import java.util.HashMap;
import java.util.Map;

/** Session-only reading position. Advancing a page never performs a game action. */
public final class GuideProgress
{
	private final Map<String, Integer> positions = new HashMap<>();

	public int position(GuidePage page)
	{
		return Math.max(0, Math.min(positions.getOrDefault(page.getId(), 0), page.getSteps().size() - 1));
	}

	public void move(GuidePage page, int delta)
	{
		positions.put(page.getId(), Math.max(0, Math.min(position(page) + delta, page.getSteps().size() - 1)));
	}

	public void restart(GuidePage page)
	{
		positions.remove(page.getId());
	}

	public void clear()
	{
		positions.clear();
	}
}

package com.xericguide;

import java.time.Instant;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** A manually requested inventory/equipment snapshot, not a live combat overlay. */
public final class KitSnapshot
{
	private static final Pattern DOSES = Pattern.compile("\\(([1-4])\\)$");
	private static final String TOOL_MATERIALS = "(?:bronze|iron|steel|black|mithril|adamant|rune|dragon|infernal|3rd age|crystal|gilded)";
	private static final Pattern AXE = Pattern.compile("^" + TOOL_MATERIALS + " (?:felling )?axe(?: \\(.*\\))?$");
	private static final Pattern PICKAXE = Pattern.compile("^" + TOOL_MATERIALS + " pickaxe(?: \\(.*\\))?$");
	private final List<String> names;
	private final Map<String, Integer> skills;
	private final Instant capturedAt;
	private final boolean available;
	private final int healingDoses;
	private final int restoreDoses;

	KitSnapshot(List<String> names, Map<String, Integer> skills, boolean available)
	{
		this.names = List.copyOf(names);
		this.skills = Map.copyOf(skills);
		this.available = available;
		this.capturedAt = Instant.now();
		healingDoses = countDoses("saradomin brew", "xeric's aid");
		restoreDoses = countDoses("super restore", "revitalisation");
	}

	public static KitSnapshot unavailable()
	{
		return new KitSnapshot(List.of(), Map.of(), false);
	}

	public boolean isAvailable() { return available; }
	public Instant getCapturedAt() { return capturedAt; }
	public Map<String, Integer> getSkills() { return skills; }
	public int getHealingDoses() { return healingDoses; }
	public int getRestoreDoses() { return restoreDoses; }

	public boolean hasPickaxe()
	{
		return names.stream().map(KitSnapshot::normalize).anyMatch(name -> PICKAXE.matcher(name).matches());
	}

	public boolean hasAxe()
	{
		return names.stream().map(KitSnapshot::normalize).anyMatch(name -> AXE.matcher(name).matches());
	}

	public boolean hasHammer()
	{
		return names.stream().map(KitSnapshot::normalize).anyMatch(name -> name.equals("hammer") || name.equals("elder maul")
			|| name.startsWith("dragon warhammer") || name.equals("abyssal bludgeon")
			|| (name.startsWith("torag's hammers") && !name.endsWith(" 0") && !name.endsWith("(0)")));
	}

	public boolean hasTinderbox()
	{
		return names.stream().map(KitSnapshot::normalize).anyMatch("tinderbox"::equals);
	}

	private int countDoses(String first, String second)
	{
		int total = 0;
		for (String raw : names)
		{
			String name = normalize(raw);
			if (name.startsWith(first) || name.startsWith(second))
			{
				Matcher matcher = DOSES.matcher(name);
				if (matcher.find())
				{
					total += Integer.parseInt(matcher.group(1));
				}
			}
		}
		return total;
	}

	private static String normalize(String name)
	{
		return name.toLowerCase(Locale.ROOT).trim();
	}
}

package com.xericguide;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/** Editorial learner advice for manually selected rooms, never a live difficulty detector. */
final class LayoutAssessment
{
	private LayoutAssessment() { }

	static List<String> describe(Set<String> rooms, PartyMode mode)
	{
		List<String> advice = new ArrayList<>();
		advice.add("Based only on the rooms you ticked and your " + mode + " learning setting. This is an editorial learning assessment, not a Wiki difficulty rating. Unselected rooms, gear, experience and extra scaling are not assessed.");
		if (rooms.isEmpty())
		{
			advice.add("Not assessed: check the native scout and select every known room above. No selection does not mean an easy raid.");
			return List.copyOf(advice);
		}
		boolean demanding = rooms.contains("vasa") || rooms.contains("vespula") || rooms.contains("vanguards") || rooms.contains("tekton");
		advice.add(demanding
			? "Consider reloading for a first completion if the challenges below are unfamiliar. Keeping this layout is reasonable when practising these rooms" + (mode == PartyMode.GROUP ? " with an experienced leader." : " and prepared for practice attempts.")
			: "No priority reload flag among your selected rooms. Continue only after checking the full layout and supplies; this is not a guarantee of an easy raid.");
		if (rooms.contains("tekton")) { advice.add("Tekton: movement mistakes are punishing and weapon choice matters. Learn the running method before committing" + (mode == PartyMode.GROUP ? "; agree a shared movement direction." : "; you handle movement and damage alone.")); }
		if (rooms.contains("vasa")) { advice.add("Vasa: opening damage, movement and crystal weapon switches can strain a learner's supplies. Bring a suitable stab option and read the opening mechanic before entering."); }
		if (rooms.contains("vespula")) { advice.add("Vespula: the portal, grubs and poison add unfamiliar mechanics. Consider another layout until you have studied a specific method and prepared its equipment."); }
		if (rooms.contains("vanguards")) { advice.add("Vanguards: their health must stay balanced to avoid resets. " + (mode == PartyMode.SOLO ? "Solo learners must manage all three combat styles and targets themselves." : "Assign targets and coordinate damage; an experienced teammate can explain when to stop.")); }
		if (rooms.contains("muttadiles")) { advice.add("Muttadiles: prepare for heavy damage and agree a meat-tree plan. A layout without the priority flags can still be dangerous here."); }
		if (rooms.contains("shamans")) { advice.add("Shamans: review poison protection and movement around their special attacks."); }
		if (rooms.contains("guardians")) { advice.add("Guardians: check your usable pickaxe and learn the attack-and-step-back rhythm."); }
		if (rooms.contains("mystics")) { advice.add("Mystics: check your ranged setup and supplies; their challenge still depends on your gear and scaling."); }
		if (rooms.contains("crabs") || rooms.contains("ice-demon") || rooms.contains("thieving") || rooms.contains("tightrope")) { advice.add("Puzzles: read each selected puzzle first. Preparation, unfamiliar solutions and tightrope combat can add time and consume supplies; do not assume a puzzle is harmless."); }
		advice.add(mode == PartyMode.SOLO ? "Olm remains the main solo learning hurdle in every layout. Read both Olm basics and Solo Olm before starting." : "Every layout still ends at Olm. Agree learner roles, supplies and a re-entry plan with your leader.");
		advice.add("To seek another Normal raid layout before committing: the raid leader can right-click the lobby stairs, choose Reload and confirm. Coordinate with your team: reloading replaces the instance and removes its players. Challenge Mode has a fixed route, so reloading will not remove its bosses.");
		advice.add("After reloading, use New run / clear checklist, inspect the new scout and select its rooms again. This plugin never reloads for you or automatically detects the new layout.");
		return List.copyOf(advice);
	}
}

package com.xericguide;

import java.util.concurrent.atomic.AtomicInteger;

/** Prevents work queued by an earlier enable from touching a replacement panel. */
final class Lifecycle
{
	private final AtomicInteger generation = new AtomicInteger();
	private volatile boolean active;

	int start()
	{
		int token = generation.incrementAndGet();
		active = true;
		return token;
	}

	void stop()
	{
		active = false;
		generation.incrementAndGet();
	}

	int token() { return generation.get(); }
	boolean accepts(int token) { return active && token == generation.get(); }
}

