package com.xericguide;

/** Facts read from raid varbits, never inferred from a boss's behaviour. */
public final class RaidContext
{
	private final boolean loggedIn;
	private final boolean inRaid;
	private final String mode;
	private final int partySize;

	private RaidContext(boolean loggedIn, boolean inRaid, String mode, int partySize)
	{
		this.loggedIn = loggedIn;
		this.inRaid = inRaid;
		this.mode = mode;
		this.partySize = partySize;
	}

	public static RaidContext unavailable()
	{
		return new RaidContext(false, false, "Unknown", 0);
	}

	static RaidContext fromValues(boolean inRaid, int challengeMode, int partySize)
	{
		String mode = !inRaid ? "Not in a raid" : challengeMode == 0 ? "Normal" : challengeMode == 1 ? "Challenge Mode" : "Unknown";
		return new RaidContext(true, inRaid, mode, inRaid && partySize >= 1 && partySize <= 100 ? partySize : 0);
	}

	public boolean isLoggedIn() { return loggedIn; }
	public boolean isInRaid() { return inRaid; }
	public String getMode() { return mode; }
	public int getPartySize() { return partySize; }
}

