/** Swing-only state. Guide navigation is always controlled by the reader. */
public final class XericGuidePanel extends PluginPanel
{
	private static final Color ACCENT = new Color(184, 220, 139);
	private static final Color MUTED = new Color(182, 185, 190);
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault());
	private final GuideBook book;
	private final XericGuideConfig config;
	private final ConfigManager configManager;
	private final Runnable requestKit;
	private final GuideProgress progress = new GuideProgress();
	private final Set<String> selectedRooms = new HashSet<>();
	private final List<JCheckBox> manualChecks = new ArrayList<>();
	private final JTabbedPane tabs = new JTabbedPane()
	{
		@Override
		public Dimension getPreferredSize()
		{
			Component selected = getSelectedComponent();
			return new Dimension(PluginPanel.PANEL_WIDTH - 12, selected == null ? 40 : selected.getPreferredSize().height + 32);
		}
	};
	private final JPanel overview = column();
	private final JPanel guide = column();
	private final JPanel supplies = column();
	private final JPanel settings = column();
	private final JComboBox<GuidePage> pageChooser;
	private final JComboBox<PartyMode> modeChooser = new JComboBox<>(PartyMode.values());
	private final JComboBox<TeamRole> roleChooser = new JComboBox<>(TeamRole.values());
	private final JTextArea raidStatus = text("", ACCENT, 13);
	private final JTextArea kitStatus = text("", MUTED, 12);
	private final JPanel assessmentBody = column();
	private final JPanel guideBody = column();
	private final JPanel kitBody = column();
	private final JCheckBox pin = new JCheckBox("Pin this guide");
	private final JCheckBox detail = new JCheckBox("First raid explanations");
	private final JSpinner textSize = new JSpinner(new SpinnerNumberModel(13, 11, 20, 1));
	private final JSpinner healingTarget = new JSpinner(new SpinnerNumberModel(0, 0, 100, 1));
	private final JSpinner restoreTarget = new JSpinner(new SpinnerNumberModel(0, 0, 100, 1));
	private KitSnapshot kit = KitSnapshot.unavailable();
	private GuidePage page;
	private boolean updating;
	private boolean stuck;

	XericGuidePanel(GuideBook book, XericGuideConfig config, ConfigManager configManager, Runnable requestKit)
	{
		assert SwingUtilities.isEventDispatchThread();
		this.book = book;
		this.config = config;
		this.configManager = configManager;
		this.requestKit = requestKit;
		page = book.get("first-raid");
		pageChooser = new JComboBox<>(book.getPages().toArray(new GuidePage[0]));
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		add(text("XERIC'S GUIDE", ACCENT, 18));
		add(text("Your first Chambers, one room at a time.", MUTED, 12));
		add(Box.createVerticalStrut(8));
		tabs.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		tabs.addTab("Start", topAligned(overview));
		tabs.addTab("Guide", topAligned(guide));
		tabs.addTab("Kit", topAligned(supplies));
		tabs.addTab("Setup", topAligned(settings));
		tabs.addChangeListener(e -> { revalidate(); repaint(); });
		tabs.setAlignmentX(LEFT_ALIGNMENT);
		add(tabs);
		buildOverview();
		buildGuide();
		buildSupplies();
		buildSettings();
		refreshSettings();
		setContext(RaidContext.unavailable(), false);
	}

	private void buildOverview()
	{
		heading(overview, "Raid overview");
		overview.add(raidStatus);
		overview.add(text("Scale: confirm the effective raid size at the party board. Player count alone does not verify additional scaling.", MUTED, 12));
		overview.add(text("Use RuneLite's Chambers of Xeric scout for the layout. Select rooms below for relevant tool reminders. Unselected does not mean absent.", MUTED, 12));
		heading(overview, "Your route (manual)");
		for (GuidePage item : book.getPages())
		{
			if (!item.getCategory().equals("Combat") && !item.getCategory().equals("Puzzle"))
			{
				continue;
			}
			JCheckBox selected = new JCheckBox(item.getTitle());
			selected.setToolTipText("Include this room in your learner assessment and tool checklist");
			selected.addActionListener(e ->
			{
				if (selected.isSelected()) { selectedRooms.add(item.getId()); }
				else { selectedRooms.remove(item.getId()); }
				renderAssessment();
				renderKit();
			});
			manualChecks.add(selected);
			overview.add(selected);
		}
		heading(overview, "Learner layout assessment");
		overview.add(assessmentBody);
		heading(overview, "Before starting");
		check(overview, "Confirm mode and scaling");
		check(overview, "Agree roles and supplies");
		check(overview, "Review equipment and charges");
		check(overview, "Read the first room guide");
		overview.add(button("Read: Your first raid", () -> selectPage("first-raid")));
		overview.add(button("Pre-Olm preparation", () -> selectPage("preparation")));
		overview.add(button("New run / clear checklist", this::resetSession));
		overview.add(text("Full layout is not the same as Challenge Mode. Choose a normal learner raid first; CM guidance is in the guide list.", MUTED, 12));
	}

	private void renderAssessment()
	{
		assessmentBody.removeAll();
		for (String advice : LayoutAssessment.describe(selectedRooms, config.partyMode()))
		{
			assessmentBody.add(text(advice, MUTED, 12));
			assessmentBody.add(Box.createVerticalStrut(6));
		}
		assessmentBody.add(button("Scouting & reload reference", () -> LinkBrowser.browse("https://oldschool.runescape.wiki/w/Chambers_of_Xeric/Strategies")));
		assessmentBody.invalidate();
		overview.invalidate();
		tabs.invalidate();
		assessmentBody.revalidate();
		assessmentBody.repaint();
		revalidate();
	}

	private void buildGuide()
	{
		guide.add(text("Choose a room or topic", ACCENT, 13));
		pageChooser.setMaximumSize(new Dimension(205, 28));
		pageChooser.setAlignmentX(LEFT_ALIGNMENT);
		pageChooser.addActionListener(e ->
		{
			GuidePage selected = (GuidePage) pageChooser.getSelectedItem();
			if (selected != null && !pin.isSelected())
			{
				page = selected;
				stuck = false;
				renderGuide();
			}
		});
		guide.add(pageChooser);
		pin.addActionListener(e -> pageChooser.setEnabled(!pin.isSelected()));
		guide.add(pin);
		guide.add(guideBody);
	}

	private void buildSupplies()
	{
		heading(supplies, "Equipment & supplies");
		supplies.add(text("Check before entering. Reads carried and worn items, excluding bank items and notes. Counts are a snapshot, not a guarantee that your loadout is suitable.", MUTED, 12));
		supplies.add(button("Check my kit", requestKit));
		supplies.add(kitStatus);
		supplies.add(kitBody);
		heading(supplies, "Check these yourself");
		check(supplies, "Melee weapon and switches");
		check(supplies, "Ranged weapon and ammunition");
		check(supplies, "Magic weapon and charges");
		check(supplies, "Spellbook, spells and runes");
		check(supplies, "Poison protection and food");
		check(supplies, "Supplies match my team plan");
		supplies.add(button("Potion recipes & preparation", () -> selectPage("preparation")));
	}

	private void buildSettings()
	{
		heading(settings, "How are you learning?");
		settings.add(modeChooser);
		settings.add(roleChooser);
		modeChooser.addActionListener(e -> save("partyMode", modeChooser.getSelectedItem()));
		roleChooser.addActionListener(e -> save("teamRole", roleChooser.getSelectedItem()));
		settings.add(detail);
		detail.addActionListener(e -> save("learnerDetail", detail.isSelected()));
		settings.add(text("Text size", MUTED, 12));
		settings.add(textSize);
		textSize.addChangeListener(e -> save("textSize", textSize.getValue()));
		heading(settings, "Your supply targets");
		settings.add(text("Targets are dose counts you choose with your mentor. Zero means unset. There is no universal safe amount for every learner.", MUTED, 12));
		settings.add(text("Healing doses (brews / aids)", MUTED, 12));
		settings.add(healingTarget);
		healingTarget.addChangeListener(e -> save("healingTarget", healingTarget.getValue()));
		settings.add(text("Restore doses", MUTED, 12));
		settings.add(restoreTarget);
		restoreTarget.addChangeListener(e -> save("restoreTarget", restoreTarget.getValue()));
		heading(settings, "About this guide");
		settings.add(text("Version 1.0.1 · James C. Offline, manually navigated reference cards. No encounter detection, combat prompts or game actions.", MUTED, 12));
		settings.add(text("Guidance reviewed 30 September 2026 using available Wiki references. Linked pages may be newer. Read them before trying an unfamiliar method.", MUTED, 12));
		settings.add(button("OSRS Wiki guide", () -> LinkBrowser.browse("https://oldschool.runescape.wiki/w/Chambers_of_Xeric/Strategies")));
		settings.add(button("Report a problem", () -> LinkBrowser.browse("https://github.com/Cornwall92/Xeric-Guide/issues")));
		settings.add(button("Jagex client guidelines", () -> LinkBrowser.browse("https://secure.runescape.com/m=news/third-party-client-guidelines?oldschool=1")));
		settings.add(text("Independent community guide; not endorsed by Jagex. All learning choices and game inputs remain yours.", MUTED, 12));
	}

	private void save(String key, Object value)
	{
		if (!updating && value != null)
		{
			configManager.setConfiguration(XericGuideConfig.GROUP, key, value);
		}
	}

	void refreshSettings()
	{
		assert SwingUtilities.isEventDispatchThread();
		updating = true;
		modeChooser.setSelectedItem(config.partyMode());
		roleChooser.setSelectedItem(config.teamRole());
		roleChooser.setEnabled(config.partyMode() == PartyMode.GROUP);
		detail.setSelected(config.learnerDetail());
		textSize.setValue(Math.max(11, Math.min(20, config.textSize())));
		healingTarget.setValue(Math.max(0, Math.min(100, config.healingTarget())));
		restoreTarget.setValue(Math.max(0, Math.min(100, config.restoreTarget())));
		updating = false;
		renderAssessment();
		renderGuide();
		renderKit();
	}

	void setContext(RaidContext context, boolean reset)
	{
		assert SwingUtilities.isEventDispatchThread();
		if (reset) { resetSession(); }
		if (!context.isLoggedIn()) { invalidateKit(); }
		String status = !context.isLoggedIn() ? "Raid information unavailable while logged out or loading. You can still read every guide."
			: !context.isInRaid() ? "Outside Chambers of Xeric. Plan your first raid here."
			: "Detected: " + context.getMode() + ". Party: " + (context.getPartySize() == 0 ? "Unknown" : context.getPartySize()) + ".";
		raidStatus.setText(status);
		raidStatus.setAlignmentX(LEFT_ALIGNMENT);
		revalidate();
	}

	void setKit(KitSnapshot snapshot)
	{
		assert SwingUtilities.isEventDispatchThread();
		kit = snapshot;
		renderKit();
	}

	void invalidateKit()
	{
		if (kit.isAvailable())
		{
			kit = KitSnapshot.unavailable();
			renderKit();
		}
	}

	private void renderKit()
	{
		kitBody.removeAll();
		kitStatus.setText(kit.isAvailable() ? "Checked " + TIME.format(kit.getCapturedAt()) + " · carried + worn"
			: "Not checked / changed. Press Check my kit while logged in.");
		if (!kit.isAvailable())
		{
			kitBody.add(text("Item results are unknown. Your manual checklist below remains available.", MUTED, 12));
		}
		else
		{
			boolean all = selectedRooms.isEmpty();
			if (all) { kitBody.add(text("No route selected: showing general tool reminders.", MUTED, 12)); }
			if (all || selectedRooms.contains("guardians"))
			{
				tool("Pickaxe", kit.hasPickaxe(), "Guardians require one. An iron pickaxe is available in their room; a better usable pickaxe is recommended.");
			}
			if (all || selectedRooms.contains("ice-demon") || selectedRooms.contains("muttadiles"))
			{
				tool("Woodcutting axe", kit.hasAxe(), "For Ice Demon kindling / a meat-tree chopping plan. Both rooms have a bronze axe spawn. Check an alternative tree strategy with your team.");
			}
			if (all || selectedRooms.contains("crabs"))
			{
				tool("Hammer / supported blunt weapon", kit.hasHammer(), "For stunning crabs. A hammer spawns in the room. Other alternatives may exist; this check is not exhaustive.");
			}
			if (all || selectedRooms.contains("ice-demon"))
			{
				tool("Tinderbox", kit.hasTinderbox(), "Available in the Ice Demon room for lighting braziers.");
			}
			kitBody.add(text(target("Healing", kit.getHealingDoses(), config.healingTarget()), ACCENT, 13));
			kitBody.add(text(target("Restores", kit.getRestoreDoses(), config.restoreTarget()), ACCENT, 13));
			kitBody.add(text("Counts cover recognised brew/aid and super restore/revitalisation names. Food, prayer potions, stored supplies and charges need manual checking.", MUTED, 12));
			kit.getSkills().forEach((name, level) -> kitBody.add(text(name + ": " + level + " (base)", MUTED, 12)));
		}
		kitBody.revalidate();
		revalidate();
		kitBody.repaint();
	}

	static String target(String name, int doses, int requested)
	{
		int goal = Math.max(0, Math.min(100, requested));
		return name + ": " + doses + " doses" + (goal == 0 ? " · target unset" : " / " + goal + " · " + (doses >= goal ? "your target met" : (goal - doses) + " short"));
	}

	private void tool(String name, boolean found, String explanation)
	{
		kitBody.add(text((found ? "FOUND · " : "NOT CARRIED · ") + name, found ? ACCENT : new Color(238, 191, 116), 13));
		kitBody.add(text(explanation, MUTED, 12));
		kitBody.add(Box.createVerticalStrut(5));
	}

	void selectPage(String id)
	{
		if (pin.isSelected())
		{
			pin.setSelected(false);
			pageChooser.setEnabled(true);
		}
		pageChooser.setSelectedItem(book.get(id));
		tabs.setSelectedIndex(1);
	}

	private void renderGuide()
	{
		guideBody.removeAll();
		int size = Math.max(11, Math.min(20, config.textSize()));
		heading(guideBody, page.getTitle());
		guideBody.add(text(config.partyMode() + " learning · " + page.getCategory(), MUTED, 12));
		if (config.learnerDetail())
		{
			guideBody.add(text("BEFORE YOU ENTER", ACCENT, 12));
			guideBody.add(text(page.getBefore(), Color.WHITE, size));
		}
		guideBody.add(text(config.partyMode() == PartyMode.SOLO ? page.getSolo() : page.getGroup(), MUTED, size));
		if (page.getId().equals("crabs"))
		{
			guideBody.add(text("Static colour reference", ACCENT, 12));
			guideBody.add(referenceTable(new String[][] {
				{"Target", "Orb", "Attack"}, {"Black", "White", "None"}, {"Yellow", "Blue", "Magic"},
				{"Cyan", "Red", "Melee"}, {"Magenta", "Green", "Ranged"}
			}));
		}
		if (page.getId().equals("olm"))
		{
			guideBody.add(text("Olm's targets (reference)", ACCENT, 12));
			guideBody.add(referenceTable(new String[][] {
				{"Target", "Style"}, {"Left hand", "Melee"}, {"Right hand", "Magic"}, {"Head (final)", "Ranged"}
			}));
		}
		if (config.partyMode() == PartyMode.GROUP && page.getId().startsWith("olm"))
		{
			guideBody.add(text(config.teamRole().getAdvice(), ACCENT, size));
		}
		int index = progress.position(page);
		guideBody.add(Box.createVerticalStrut(8));
		guideBody.add(text("READING STEP " + (index + 1) + " OF " + page.getSteps().size(), ACCENT, 12));
		guideBody.add(text(page.getSteps().get(index), Color.WHITE, size));
		JPanel controls = new JPanel(new GridLayout(1, 2, 5, 0));
		JButton back = button("Back", () -> { progress.move(page, -1); renderGuide(); });
		JButton next = button("Next", () -> { progress.move(page, 1); renderGuide(); });
		back.setEnabled(index > 0);
		next.setEnabled(index < page.getSteps().size() - 1);
		controls.add(back);
		controls.add(next);
		controls.setAlignmentX(LEFT_ALIGNMENT);
		controls.setMaximumSize(new Dimension(178, 28));
		guideBody.add(controls);
		guideBody.add(button("Read from beginning", () -> { progress.restart(page); renderGuide(); }));
		guideBody.add(button(stuck ? "Hide recovery advice" : "I'm stuck", () -> { stuck = !stuck; renderGuide(); }));
		if (stuck) { guideBody.add(text(page.getRecovery(), new Color(238, 191, 116), size)); }
		guideBody.add(button("Open Wiki reference", () -> LinkBrowser.browse(page.getSource())));
		guideBody.add(text("Read ahead before fighting. Next changes this page only; it does not detect your progress or perform any action.", MUTED, 11));
		guideBody.revalidate();
		revalidate();
		guideBody.repaint();
	}

	void resetSession()
	{
		progress.clear();
		selectedRooms.clear();
		renderAssessment();
		manualChecks.forEach(check -> check.setSelected(false));
		kit = KitSnapshot.unavailable();
		stuck = false;
		if (!pin.isSelected()) { pageChooser.setSelectedItem(book.get("first-raid")); }
		renderGuide();
		renderKit();
	}

	private void check(JPanel parent, String label)
	{
		JCheckBox check = new JCheckBox(label);
		check.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		manualChecks.add(check);
		parent.add(check);
	}

	private static JPanel column()
	{
		JPanel panel = new JPanel()
		{
			@Override
			protected void addImpl(Component component, Object constraints, int index)
			{
				if (component instanceof JComponent)
				{
					((JComponent) component).setAlignmentX(LEFT_ALIGNMENT);
				}
				super.addImpl(component, constraints, index);
			}
		};
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 4, 6, 4));
		panel.setAlignmentX(LEFT_ALIGNMENT);
		return panel;
	}

	private static JTable referenceTable(String[][] rows)
	{
		JTable table = new JTable(rows, rows[0])
		{
			@Override
			public boolean isCellEditable(int row, int column) { return false; }
		};
		table.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		table.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		table.setForeground(Color.WHITE);
		table.setGridColor(Color.GRAY);
		table.setRowHeight(22);
		table.setTableHeader(null);
		table.setRowSelectionAllowed(false);
		table.setFocusable(false);
		table.setPreferredSize(new Dimension(178, rows.length * 22));
		table.setMaximumSize(table.getPreferredSize());
		return table;
	}

	private static void heading(JPanel parent, String title)
	{
		parent.add(Box.createVerticalStrut(8));
		parent.add(text(title, ACCENT, 15));
		parent.add(Box.createVerticalStrut(5));
	}

	private static JButton button(String title, Runnable action)
	{
		JButton button = new JButton(title);
		button.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		button.setAlignmentX(LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(205, 30));
		button.addActionListener(e -> action.run());
		return button;
	}

	private static JPanel topAligned(JPanel content)
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(content, BorderLayout.NORTH);
		return wrapper;
	}

	private static JTextArea text(String value, Color color, int size)
	{
		JTextArea text = new JTextArea(value)
		{
			@Override
			public Dimension getPreferredSize()
			{
				setSize(178, Short.MAX_VALUE);
				Dimension preferred = super.getPreferredSize();
				return new Dimension(178, preferred.height);
			}

			@Override
			public Dimension getMaximumSize()
			{
				return getPreferredSize();
			}
		};
		text.setEditable(false);
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setOpaque(false);
		text.setForeground(color);
		text.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, size));
		text.setAlignmentX(LEFT_ALIGNMENT);
		text.setBorder(BorderFactory.createEmptyBorder(3, 0, 4, 0));
		return text;
	}
}

package com.xericguide;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
