@PluginDescriptor(
	name = "Xeric's Guide",
	description = "A beginner's manual Chambers of Xeric guide for solo and group raids",
	tags = {"chambers", "xeric", "cox", "beginner", "guide", "solo", "group"},
	internalName = "xeric-guide"
)
public class XericGuidePlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(XericGuidePlugin.class);
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ItemManager itemManager;
	@Inject private ConfigManager configManager;
	@Inject private XericGuideConfig config;
	@Inject private ScheduledExecutorService executor;

	private final Lifecycle lifecycle = new Lifecycle();
	private Future<?> resourceLoad;
	// These references are only read or written on the Swing event dispatch thread.
	private XericGuidePanel panel;
	private NavigationButton navigation;
	// These values are only used on the client thread.
	private boolean inRaid;
	private int partyId = -1;

	@Provides
	XericGuideConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(XericGuideConfig.class);
	}

	@Override
	protected void startUp()
	{
		int token = lifecycle.start();
		resourceLoad = executor.submit(() ->
		{
			GuideBook book = GuideBook.load();
			BufferedImage icon = loadIcon();
			onEdt(token, () ->
			{
				panel = new XericGuidePanel(book, config, configManager, this::requestKit);
				navigation = NavigationButton.builder().tooltip("Xeric's Guide").icon(icon).priority(6).panel(panel).build();
				clientToolbar.addNavigation(navigation);
				clientThread.invokeLater(() ->
				{
					if (lifecycle.accepts(token))
					{
						inRaid = false;
						partyId = -1;
						publishContext(token);
					}
				});
			});
		});
	}

	@Override
	protected void shutDown()
	{
		lifecycle.stop();
		if (resourceLoad != null)
		{
			resourceLoad.cancel(true);
			resourceLoad = null;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (navigation != null)
			{
				clientToolbar.removeNavigation(navigation);
				navigation = null;
			}
			panel = null;
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		int token = lifecycle.token();
		if (!lifecycle.accepts(token))
		{
			return;
		}
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			publishContext(token);
		}
		else
		{
			boolean reset = state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST;
			if (reset)
			{
				inRaid = false;
				partyId = -1;
			}
			onPanel(token, () -> panel.setContext(RaidContext.unavailable(), reset));
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.RAIDS_CLIENT_INDUNGEON
			|| event.getVarbitId() == VarbitID.RAIDS_CHALLENGE_MODE
			|| event.getVarbitId() == VarbitID.RAIDS_CLIENT_PARTYSIZE
			|| event.getVarpId() == VarPlayerID.RAIDS_PARTY_GROUPHOLDER)
		{
			publishContext(lifecycle.token());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
		{
			onPanel(lifecycle.token(), () -> panel.invalidateKit());
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (XericGuideConfig.GROUP.equals(event.getGroup()))
		{
			onPanel(lifecycle.token(), () -> panel.refreshSettings());
		}
	}

	private void publishContext(int token)
	{
		if (!lifecycle.accepts(token))
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			onPanel(token, () -> panel.setContext(RaidContext.unavailable(), false));
			return;
		}
		try
		{
			boolean nowInRaid = client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
			int currentParty = client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER);
			boolean reset = (inRaid && !nowInRaid) || (partyId != -1 && currentParty != partyId);
			inRaid = nowInRaid;
			partyId = currentParty;
			RaidContext context = RaidContext.fromValues(nowInRaid,
				client.getVarbitValue(VarbitID.RAIDS_CHALLENGE_MODE), client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE));
			onPanel(token, () -> panel.setContext(context, reset));
		}
		catch (RuntimeException ex)
		{
			log.debug("Raid context unavailable during transition", ex);
			onPanel(token, () -> panel.setContext(RaidContext.unavailable(), false));
		}
	}

	private void requestKit()
	{
		int token = lifecycle.token();
		clientThread.invokeLater(() ->
		{
			if (!lifecycle.accepts(token))
			{
				return;
			}
			KitSnapshot snapshot = captureKit();
			onPanel(token, () -> panel.setKit(snapshot));
		});
	}

	private KitSnapshot captureKit()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return KitSnapshot.unavailable();
		}
		try
		{
			ItemContainer inventory = client.getItemContainer(InventoryID.INV);
			ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
			if (inventory == null || equipment == null)
			{
				return KitSnapshot.unavailable();
			}
			List<String> names = new ArrayList<>();
			collectItems(inventory, names);
			collectItems(equipment, names);
			Map<String, Integer> skills = new LinkedHashMap<>();
			for (Skill skill : List.of(Skill.HERBLORE, Skill.FARMING, Skill.CONSTRUCTION, Skill.MINING, Skill.WOODCUTTING, Skill.THIEVING))
			{
				skills.put(skill.getName(), client.getRealSkillLevel(skill));
			}
			return new KitSnapshot(names, skills, true);
		}
		catch (RuntimeException ex)
		{
			log.debug("Kit check unavailable", ex);
			return KitSnapshot.unavailable();
		}
	}

	private void collectItems(ItemContainer container, List<String> names)
	{
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			ItemComposition definition = itemManager.getItemComposition(item.getId());
			if (definition.getNote() == -1 && definition.getName() != null)
			{
				names.add(definition.getName());
			}
		}
	}

	private void onPanel(int token, Runnable work)
	{
		onEdt(token, () ->
		{
			if (panel != null)
			{
				work.run();
			}
		});
	}

	private void onEdt(int token, Runnable work)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (lifecycle.accepts(token))
			{
				work.run();
			}
		});
	}

	private BufferedImage loadIcon()
	{
		try (InputStream input = getClass().getResourceAsStream("icon.png"))
		{
			BufferedImage image = input == null ? null : ImageIO.read(input);
			if (image != null)
			{
				return image;
			}
		}
		catch (IOException ex)
		{
			log.debug("Unable to load sidebar icon", ex);
		}
		// A corrupt optional image must not prevent opening the reference guide.
		BufferedImage fallback = new BufferedImage(20, 20, BufferedImage.TYPE_INT_ARGB);
		java.awt.Graphics2D graphics = fallback.createGraphics();
		graphics.setColor(new java.awt.Color(177, 214, 126));
		graphics.fillRoundRect(3, 2, 14, 16, 3, 3);
		graphics.setColor(java.awt.Color.DARK_GRAY);
		graphics.drawLine(7, 6, 14, 6);
		graphics.drawLine(7, 10, 14, 10);
		graphics.dispose();
		return fallback;
	}
}

package com.xericguide;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.*;

public class GuideBookTest
{
	@Test
	public void everyBundledGuideIsReadableAndHasUsefulContent() throws Exception
	{
		for (String id : GuideBook.IDS)
		{
			try (java.io.InputStream stream = GuideBook.class.getResourceAsStream("guides/" + id + ".properties"))
			{
				GuidePage page = GuideBook.parse(id, stream);
				assertTrue(id, page.getSteps().size() >= 4);
				assertFalse(id, page.getTitle().contains("unavailable"));
				assertNotEquals(id, page.getSolo(), page.getGroup());
				assertFalse(id, page.getRecovery().isBlank());
			}
		}
		assertEquals(19, GuideBook.load().getPages().size());
	}

	@Test(expected = IOException.class)
	public void missingResourceIsReported() throws Exception
	{
		GuideBook.parse("missing", null);
	}

	@Test(expected = IOException.class)
	public void malformedResourceDoesNotBecomeAnEmptyGuide() throws Exception
	{
		GuideBook.parse("broken", new ByteArrayInputStream("title=Only a title".getBytes(StandardCharsets.UTF_8)));
	}

