package com.xericguide;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.List;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.JTabbedPane;
import javax.swing.JCheckBox;
import javax.swing.SwingUtilities;

/** Paints Swing components offscreen. Does not start RuneLite or interact with the game. */
public final class PanelPreview
{
	private PanelPreview() { }

	public static void main(String[] args) throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				GuideBook book = GuideBook.load();
				XericGuidePanel panel = new XericGuidePanel(book, new XericGuideConfig() {}, null, () -> {});
				panel.setContext(RaidContext.fromValues(true, 0, 3), false);
				panel.setKit(new KitSnapshot(List.of("Dragon pickaxe", "Rune axe", "Hammer", "Xeric's aid (+)(4)", "Revitalisation (+)(4)"), Map.of("Herblore", 78), true));
				File dir = new File("build/previews");
				if (!dir.isDirectory() && !dir.mkdirs()) { throw new IllegalStateException("Cannot create preview directory"); }
				JTabbedPane tabs = findTabs(panel);
				for (int i = 0; i < tabs.getTabCount(); i++)
				{
					tabs.setSelectedIndex(i);
					if (i == 1) { panel.selectPage("olm-group"); }
					paint(panel, new File(dir, "tab-" + i + ".png"));
				}
				for (GuidePage page : book.getPages())
				{
					panel.selectPage(page.getId());
					paint(panel, new File(dir, page.getId() + ".png"));
				}
				tabs.setSelectedIndex(0);
				selectRoom(panel, "Vanguards");
				paint(panel, new File(dir, "layout-assessment.png"));
			}
			catch (Exception ex)
			{
				throw new IllegalStateException(ex);
			}
		});
	}

	private static JTabbedPane findTabs(Container parent)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof JTabbedPane) { return (JTabbedPane) child; }
		}
		throw new IllegalStateException("No tabs");
	}

	private static void selectRoom(Container parent, String name)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof JCheckBox && ((JCheckBox) child).getText().equals(name))
			{
				((JCheckBox) child).doClick();
			}
			else if (child instanceof Container) { selectRoom((Container) child, name); }
		}
	}

	private static void paint(XericGuidePanel panel, File output) throws Exception
	{
		invalidateTree(panel);
		int width = 225;
		int height = Math.max(900, panel.getPreferredSize().height);
		panel.setSize(width, height);
		layout(panel);
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setColor(Color.DARK_GRAY);
		graphics.fillRect(0, 0, width, height);
		panel.printAll(graphics);
		graphics.dispose();
		ImageIO.write(image, "png", output);
	}

	private static void layout(Container parent)
	{
		parent.doLayout();
		for (Component child : parent.getComponents())
		{
			if (child instanceof Container) { layout((Container) child); }
		}
	}

	private static void invalidateTree(Container parent)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof Container) { invalidateTree((Container) child); }
		}
		parent.invalidate();
	}
}

